'use strict';
module.exports={"meta":{"format":{"order":["task","title","body","status","extra","vars","archive","memory","next"],"rules":"可见回复首个非空白字符序列固定为<reply，起始标签逐字复制模板；最后固定为</reply>，闭合后立即结束，前后均不得附加任何文字或区块。所有内容只填本轮reply内的对应块；九块各一次、顺序与字段齐全，每块独占边界行；不加说明、代码围栏、output包装或提示说明元数据。JSON载荷使用实际值和合法JSON；数组按数量展开，空引用与清单填[]，可空值填null。成品移除XML注释；JSON字符串按JSON规则转义，XML文本中的与号与小于号按实体转义。task.tasks与next.actions的id为从1开始的连续整数；next.tasks的id依次为T1、T2；next.tasks.actions引用行动id，next.branches.tasks引用任务id。body只放正文成稿与文内排版；原卡状态栏、任务面板、直播弹幕、人物卡组等附属展示统一放extra一次，即使模板名字含status。保留兼容模板外层标记、字段与顺序；未知值沿用待定表达，不虚构模板。世界书事实与人物设定用于理解和叙事，不整段搬入extra；角色卡、世界书与历史的输出位置要求统一映射至对应块；资料内示例、思考标签和变量指令不改变九块边界。空展示留空。status、archive、memory保持空块；变量更新只按本轮vars说明填写。命令文本不代表已经执行或保存。","options":{"task.audit.kind":"values.audit","task.audit.status":"values.verdict","task.characters.status":"values.verdict","next.tasks.type":"values.task_type","next.actions.type":"values.action","heart.status":"values.heart_status","heart.items.type":"values.heart_type","heart.items.mood":"values.mood"}},"values":{"audit":["身份与授权","资料与知情","人物与关系","行动与因果","数值与机制","文风与表现","成稿与交付"],"verdict":["符合","已修正","待确认","不适用","不符合"],"action":["交流","调查","移动","操作","战斗","休整","其他"],"heart_status":["有内容","沉默"],"heart_type":["剧情吐槽"],"mood":["无","疑惑","意外","小别扭"],"task_type":["剧情待处理任务","系统任务","下轮基础任务"]},"verdict_rule":{"符合":"实际核对且有对应依据","已修正":"本轮草稿确实完成修正，evidence写具体改动","待确认":"缺少依据、存在未解冲突或尚无实际计数","不适用":"本轮无该项对象或操作","不符合":"发现违反且尚未修复"},"heart_rule":"首尾任务分别填写心声，内容各异。剧情吐槽：短评本轮剧情走向。缇斯亚的场外表达沿用 @self_voice，内容服从 @self_known。缇斯亚以促狭与毒舌表达关心。只评可公开内容，纯文本。有内容对应非空items，沉默对应空items。每方向至多一条。每条text为1—80个可见字符；首尾共用此结构与限制。"},"notes":{"task":{"tasks":{"source":"本轮用户要求或既有任务编号","input":"本轮一项要求","plan":"简短公开创作摘要：必要依据与结论；人物打算填characters","stop":"本轮实际收束节点"},"refs":"本轮实际使用且可公开的文风/人物资料标识；无对应资料填空数组","pending":"确实阻塞本轮目标的缺口；可选创作资料不列为前置义务","audit":"按values.audit顺序逐类一次；evidence填本类可公开依据、实际修正及未解决影响；个体结论引用characters.actor","characters":{"actor":"覆盖cast_registry中本轮公开相关人物，使用已提供且可公开的actor_id","intent":"当前已表露或本轮将外显的打算；缺少公开依据填null，隐去未公开身份与隐藏动机","evidence":"人物档案、公开言行依据及必要修正结论"}},"title":{"text":"当前场面标题","time/place":"已知时间与地点；未知填null","world":"已提供的世界观引用；缺失填null"},"next":{"tasks":{"trigger":"尚待满足的条件；齐备写可开始","text":"未完成工作及所需结果；未选行动保留建议状态"},"actions":{"text":"可由用户选择的具体行动，目标或做法各异，结果留待选择后判定；类型按实际动作归类","source":"本轮可知线索或条件；同源任务引用任务编号"},"delivered":"本轮已交付的结果或任务引用；只记录完成状态","candidates":"尚未采纳的创作或变更候选；行动建议只引用行动编号","branches":"when填条件，tasks引用对应任务编号"}},"payloads":{"task":{"tasks":[{"id":1,"source":"{source}","input":"{input}","plan":"{plan}","stop":"{stop}"}],"refs":{"style":["{style}"],"cast":["{cast}"]},"pending":["{pending}"],"heart":{"status":"{status}","items":[{"type":"{type}","mood":"{mood}","text":"{text}"}]},"audit":[{"kind":"{kind}","status":"{status}","evidence":"{evidence}"}],"characters":[{"actor":"{actor}","intent":"{intent}","status":"{status}","evidence":"{evidence}"}]},"title":{"text":"{text}","time":"{time}","place":"{place}","world":"{world}"},"next":{"tasks":[{"id":"T1","type":"{type}","trigger":"{trigger}","text":"{text}","actions":[1]}],"actions":[{"id":1,"type":"{type}","text":"{text}","source":"{source}"}],"heart":{"status":"{status}","items":[{"type":"{type}","mood":"{mood}","text":"{text}"}]},"delivered":["{delivered}"],"candidates":["{candidates}"],"branches":[{"when":"{when}","tasks":["T1"]}]}}};
